let p: FABContract & { style?:string } = $props();
const uid=$props.id();function validate(){if(p.actions&&p.actions.length>3)throw new RangeError("FAB supports at most three actions");}validate();$effect(validate);const expanded=control(()=>p.expanded,untrack(()=>p.defaultExpanded),false,expanded=>p.onExpandedChange?.({expanded}));let trigger:HTMLButtonElement;function collapse(){expanded.request(false);void tick().then(()=>{if(!expanded.value)trigger?.focus();});}function close(e:KeyboardEvent){if(!p.disabled&&!ignoredKey(e)&&e.key==='Escape'&&expanded.value){e.preventDefault();collapse();}}
